#!/usr/bin/env node
/*
 * M8.1 gate: every gallery code snippet must compile. Extracts the template
 * literals from snippets.ts, wraps each into a component with the imports it
 * references and typechecks the generated file with the demo tsconfig.
 */
import { execSync } from "node:child_process";
import { readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const snippetsPath = join(root, "examples/demo/src/apps/gallery/snippets.ts");
const source = readFileSync(snippetsPath, "utf8");

const snippets = [];
const re = /^\s{2}(?:"([\w-]+)"|([\w-]+)):\s`([\s\S]*?)`,?$/gm;
for (let m; (m = re.exec(source)); ) {
  snippets.push({ slug: m[1] ?? m[2], code: m[3] });
}
if (snippets.length < 10) {
  console.error(`check-snippets: extraction looks broken (found ${snippets.length})`);
  process.exit(1);
}

const names = new Set();
for (const { code } of snippets) {
  for (const id of code.match(/\b(?:TK[A-Za-z]+|ruLocale|enLocale)\b/g) ?? []) names.add(id);
}

const out = [
  "/* AUTO-GENERATED by scripts/check-snippets.mjs — never committed. */",
  `import { ${[...names].sort().join(", ")} } from "tg-mini-app-uikit";`,
  "",
  ...snippets.map(
    ({ slug, code }, i) =>
      `export function Snippet_${i} /* ${slug} */ () {\n  return (\n${code
        .split("\n")
        .map((l) => "    " + l)
        .join("\n")}\n  );\n}`,
  ),
  "",
].join("\n");

const target = join(root, "examples/demo/src/__snippets_check__.tsx");
writeFileSync(target, out);
try {
  execSync("npx tsc --noEmit", { cwd: join(root, "examples/demo"), stdio: "inherit" });
  console.log(`✓ ${snippets.length} gallery snippets compile`);
} finally {
  rmSync(target, { force: true });
}
